package hasher

import (
	"crypto/rand"
	"encoding/binary"
	"hash/maphash"
	"sync"
)

var instance = NewHasher()

func Reseed(id string) {
	instance.Reseed(id)
}

func SetSeed(id, seed string) {
	instance.SetSeed(id, seed)
}

func HashFunc() func(id, str string) uint64 {
	return instance.HashFunc()
}

// Hasher maintains a seed for each identifier and a hash seed shared by its hashes.
type Hasher struct {
	mu       sync.Mutex
	seeds    map[string]string
	hashSeed maphash.Seed
}

func NewHasher() *Hasher {
	return &Hasher{
		seeds:    make(map[string]string),
		hashSeed: maphash.MakeSeed(),
	}
}

// SetSeed assigns a reproducible seed to the given id.
func (h *Hasher) SetSeed(id, seed string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.seeds[id] = seed
}

// Reseed generates a new seed for the given id.
func (h *Hasher) Reseed(id string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.seeds[id] = randomSeed()
}

func randomSeed() string {
	var seed [16]byte
	if _, err := rand.Read(seed[:]); err != nil {
		panic(err)
	}
	return string(seed[:])
}

// HashFunc returns a function that hashes a string using the seed for the given id.
func (h *Hasher) HashFunc() func(id, str string) uint64 {
	return func(id, str string) uint64 {
		h.mu.Lock()
		seed, ok := h.seeds[id]
		if !ok {
			seed = randomSeed()
			h.seeds[id] = seed
		}
		h.mu.Unlock()

		var hash maphash.Hash
		hash.SetSeed(h.hashSeed)
		var length [8]byte
		binary.LittleEndian.PutUint64(length[:], uint64(len(seed)))
		_, _ = hash.Write(length[:])
		_, _ = hash.WriteString(seed)
		_, _ = hash.WriteString(str)
		return hash.Sum64()
	}
}
